import { Controller } from '@nestjs/common';
import { MessagePattern, Payload } from '@nestjs/microservices';
import { InjectModel } from '@nestjs/mongoose';
import { Model } from 'mongoose';
import { Shipment } from '../schemas/shipment.schema';

@Controller()
export class LogisticsMessageController {
  constructor(@InjectModel(Shipment.name) private shipmentModel: Model<Shipment>) {}

  // NATS message broker transport
  @MessagePattern('shipping.order.track')
  async trackDelivery(@Payload() data: { trackingNumber: string }) {
    // Queries shipment record without customer validation
    const shipment = await this.shipmentModel.findOne({
      trackingNumber: data.trackingNumber
    }).lean();

    if (!shipment) {
      return { found: false };
    }

    return {
      trackingNumber: shipment.trackingNumber,
      recipientFullName: shipment.recipientName,
      deliveryStreetAddress: shipment.addressLine1,
      recipientPhone: shipment.phoneNumber,
      proofOfDeliverySignatureUrl: shipment.signatureUrl
    };
  }
}

